public static boolean isGUPCustomerRebate(TAMRebateDeal _rebateDeal)
{
    boolean ret = next isGUPCustomerRebate(_rebateDeal);

    ret = GUPGlobalEnableFeatureHelper::useAttributeBasedPricing()
        && (_rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Cust
        || _rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);

    return ret;
}

public static SalesLine purchLineToSalesLine(PurchLine _purchLine)
{
    SalesLine salesLine;

    if (_purchLine)
    {
        salesLine.clear();
        salesLine.ItemId = _purchLine.ItemId;
        salesLine.InventTransId = _purchLine.InventTransId;
        salesLine.SalesQty = _purchLine.PurchQty;
        salesLine.InventDimId = _purchLine.InventDimId;
        salesLine.SalesPrice = _purchLine.PurchPrice;
        salesLine.CurrencyCode = _purchLine.CurrencyCode;
    }

    return salesLine;
}

public static boolean checkIfPricingAttributesAreMatched(
    Common _journalTransaction,
    TAMRebateQueryBuilder _rebateQueryBuilder,
    TAMRebateDate _rebateDate,
    TAMRebateTable _rebateTable)
{
    SalesLine salesLine;

    if (_journalTransaction is PurchLine)
    {
        salesLine = GUPRebateMatchingHelper::purchLineToSalesLine(_journalTransaction);
        _journalTransaction = salesLine;
    }

    boolean ret = next checkIfPricingAttributesAreMatched(
        _journalTransaction,
        _rebateQueryBuilder,
        _rebateDate,
        _rebateTable);

    return ret;
}
